import test from 'node:test';
import assert from 'node:assert/strict';
import {
  normalizeProtocol,
  stabilize,
  computeBackReferences,
  parseRoute,
  formatRoute,
  normalizeTarget,
  getRedirect,
} from '../src/protocol-model.js';

/** @import { TestContext } from 'node:test' */
/** @import { ProtocolDomain, ProtocolType } from '../types/types.d.ts' */

test('normalizeTarget', () => {
  assert.equal(normalizeTarget('tot'), 'tot');
  assert.equal(normalizeTarget('stable'), 'stable');
  assert.equal(normalizeTarget('1-3'), 'stable');
  assert.equal(normalizeTarget('1-2'), 'stable');
  assert.equal(normalizeTarget('v8'), 'v8');
  assert.equal(normalizeTarget(''), 'tot');
  assert.equal(normalizeTarget(null), 'tot');
  assert.equal(normalizeTarget('unknown'), 'tot');
});

test('normalizeProtocol: sets empty array defaults', () => {
  /** @type {any} */
  const raw = {
    domains: [
      {
        domain: 'Sample',
      },
    ],
  };

  const normalized = normalizeProtocol(raw);

  assert.deepEqual(normalized.domains[0]?.commands, []);
  assert.deepEqual(normalized.domains[0]?.events, []);
  assert.deepEqual(normalized.domains[0]?.types, []);

  // Assert input object was not mutated
  assert.equal(raw.domains[0].commands, undefined);
  assert.equal(raw.domains[0].events, undefined);
  assert.equal(raw.domains[0].types, undefined);
});

test('normalizeProtocol: deterministic sorting (experimental, deprecated, optional, alphabetical)', () => {
  const raw = {
    domains: [
      {
        domain: 'Alpha',
        commands: [
          { name: 'zetaExp', experimental: true },
          { name: 'beta' },
          { name: 'alpha' },
          { name: 'alphaDep', deprecated: true },
        ],
      },
    ],
  };

  const normalized = normalizeProtocol(raw);
  const commandNames = (normalized.domains[0]?.commands || []).map(
    (/** @type {{name: string}} */ c) => c.name,
  );

  // Standard alphabetical first, then experimental, then deprecated
  assert.deepEqual(commandNames, ['alpha', 'beta', 'zetaExp', 'alphaDep']);
});

test('normalizeProtocol: does NOT mutate input objects (delete object.experimental)', () => {
  const raw = {
    domains: [
      {
        domain: 'ExperimentalDomain',
        experimental: true,
        commands: [
          {
            name: 'expCommand',
            experimental: true,
          },
        ],
      },
    ],
  };

  const normalized = normalizeProtocol(raw);

  // In normalized output, redundant experimental flag on child is pruned
  assert.equal(normalized.domains[0]?.experimental, true);
  assert.equal(normalized.domains[0]?.commands[0]?.experimental, undefined);

  // Input object must retain experimental: true
  assert.equal(raw.domains[0].commands[0].experimental, true);
});

test('stabilize: deep immutability and filtering experimental entities', () => {
  const original = {
    domain: 'TestDomain',
    experimental: false,
    commands: [
      { name: 'stableCommand', experimental: false },
      { name: 'expCommand', experimental: true },
    ],
    types: [
      {
        id: 'StableType',
        properties: [
          { name: 'propA', experimental: false },
          { name: 'propB', experimental: true },
        ],
      },
      {
        id: 'ExpType',
        experimental: true,
      },
    ],
  };

  const stable = stabilize(original);

  // Commands filtered
  assert.equal(stable.commands.length, 1);
  assert.equal(stable.commands[0]?.name, 'stableCommand');

  // Types filtered
  assert.equal(stable.types.length, 1);
  assert.equal(stable.types[0]?.id, 'StableType');
  assert.equal(stable.types[0]?.properties?.length, 1);
  assert.equal(stable.types[0]?.properties?.[0]?.name, 'propA');

  // Deep clone immutability: mutating stable must not affect original
  stable.commands[0].name = 'MUTATED';
  stable.commands.push(/** @type {any} */ ({ name: 'NEW' }));
  assert.equal(original.commands[0]?.name, 'stableCommand');
  assert.equal(original.commands.length, 2);
});

test('computeBackReferences: computes reverse references with deduplication and array item $ref unpacking', () => {
  /** @type {ProtocolDomain[]} */
  const domains = [
    {
      domain: 'DOM',
      types: [
        { id: 'NodeId', type: 'integer' },
        { id: 'Node', type: 'object', properties: [{ name: 'nodeId', $ref: 'NodeId' }] },
        {
          id: 'NodeList',
          type: 'array',
          items: { $ref: 'Node' },
        },
      ],
      commands: [
        {
          name: 'describeNode',
          parameters: [{ name: 'nodeId', $ref: 'NodeId' }],
          returns: [{ name: 'node', $ref: 'Node' }],
        },
        {
          name: 'pushNodesByBackendIdsToFrontend',
          parameters: [{ name: 'backendNodeIds', $ref: 'NodeId' }],
          returns: [{ name: 'nodeIds', $ref: 'NodeId' }],
        },
      ],
      events: [
        {
          name: 'setChildNodes',
          parameters: [
            { name: 'parentId', $ref: 'NodeId' },
            {
              name: 'nodes',
              type: 'array',
              items: { $ref: 'Node' },
            },
          ],
        },
      ],
    },
  ];

  computeBackReferences(domains);

  const nodeIdType = domains[0]?.types?.find((t) => t.id === 'NodeId');
  const nodeType = domains[0]?.types?.find((t) => t.id === 'Node');

  // NodeId should be referenced by:
  // - DOM.describeNode (command)
  // - DOM.pushNodesByBackendIdsToFrontend (command - deduplicated across params and returns!)
  // - DOM.setChildNodes (event)
  // - DOM.Node (type)
  assert.ok(nodeIdType?.referencedBy);
  assert.deepEqual(nodeIdType?.referencedBy, [
    { type: 'command', name: 'DOM.describeNode' },
    { type: 'command', name: 'DOM.pushNodesByBackendIdsToFrontend' },
    { type: 'event', name: 'DOM.setChildNodes' },
    { type: 'type', name: 'DOM.Node' },
  ]);

  // Node should be referenced by:
  // - DOM.describeNode (command return)
  // - DOM.setChildNodes (event array items $ref)
  // - DOM.NodeList (type items $ref)
  assert.ok(nodeType?.referencedBy);
  assert.deepEqual(nodeType?.referencedBy, [
    { type: 'command', name: 'DOM.describeNode' },
    { type: 'event', name: 'DOM.setChildNodes' },
    { type: 'type', name: 'DOM.NodeList' },
  ]);
});

test('parseRoute: dynamic native subtests for all route formats', async (/** @type {TestContext} */ t) => {
  const cases = [
    // Standard modern hash routes
    {
      input: '#/Page.navigate',
      expected: { target: 'tot', domain: 'Page', member: 'navigate' },
    },
    {
      input: '#/Page',
      expected: { target: 'tot', domain: 'Page', member: null },
    },
    {
      input: '#/v8/Runtime.evaluate',
      expected: { target: 'v8', domain: 'Runtime', member: 'evaluate' },
    },
    {
      input: '#/stable/Network.getCookies',
      expected: { target: 'stable', domain: 'Network', member: 'getCookies' },
    },

    // Deep links and landing anchors
    {
      input: '#/endpoints',
      expected: { target: 'tot', domain: null, member: null, section: 'endpoints' },
    },
    {
      input: '#endpoints',
      expected: { target: 'tot', domain: null, member: null, section: 'endpoints' },
    },
    {
      input: '#/faq',
      expected: { target: 'tot', domain: null, member: null, section: 'faq' },
    },
    {
      input: '#faq',
      expected: { target: 'tot', domain: null, member: null, section: 'faq' },
    },
    {
      input: '#/get-devtoolsinspector.html',
      expected: { target: 'tot', domain: null, member: null, section: 'get-devtoolsinspector.html' },
    },
    {
      input: '#get-devtoolsinspector.html',
      expected: { target: 'tot', domain: null, member: null, section: 'get-devtoolsinspector.html' },
    },
    {
      input: '#/get-jsonversion',
      expected: { target: 'tot', domain: null, member: null, section: 'get-jsonversion' },
    },
    {
      input: '#get-jsonversion',
      expected: { target: 'tot', domain: null, member: null, section: 'get-jsonversion' },
    },

    // Root and empty routes
    {
      input: '#/',
      expected: { target: 'tot', domain: null, member: null },
    },
    {
      input: '',
      expected: { target: 'tot', domain: null, member: null },
    },
    {
      input: '#',
      expected: { target: 'tot', domain: null, member: null },
    },
    // Trailing slashes
    {
      input: '#/Page/',
      expected: { target: 'tot', domain: 'Page', member: null },
    },
    {
      input: '#/v8/Runtime/',
      expected: { target: 'v8', domain: 'Runtime', member: null },
    },
    {
      input: '#/v8',
      expected: { target: 'v8', domain: null, member: null },
    },
    {
      input: '#/v8/',
      expected: { target: 'v8', domain: null, member: null },
    },
    {
      input: '#/stable',
      expected: { target: 'stable', domain: null, member: null },
    },
    {
      input: '#/stable/',
      expected: { target: 'stable', domain: null, member: null },
    },
  ];

  for (const { input, expected } of cases) {
    await t.test(`parseRoute("${input}")`, () => {
      const result = parseRoute(input);
      assert.deepEqual(result, expected);
    });
  }
});

test('formatRoute: canonical route formatting', () => {
  // Tot target formats without prefix
  assert.equal(
    formatRoute({ target: 'tot', domain: 'Page', member: 'navigate' }),
    '#/Page.navigate',
  );
  assert.equal(formatRoute({ target: 'tot', domain: 'Page', member: null }), '#/Page');
  assert.equal(formatRoute({ target: 'tot', domain: null, member: null }), '#/');

  // V8 target formats with v8/ prefix
  assert.equal(
    formatRoute({ target: 'v8', domain: 'Runtime', member: 'evaluate' }),
    '#/v8/Runtime.evaluate',
  );
  assert.equal(formatRoute({ target: 'v8', domain: 'Runtime', member: null }), '#/v8/Runtime');
  assert.equal(formatRoute({ target: 'v8', domain: null, member: null }), '#/v8/');

  // Stable target formats with stable/ prefix
  assert.equal(
    formatRoute({ target: 'stable', domain: 'Network', member: 'getCookies' }),
    '#/stable/Network.getCookies',
  );
  assert.equal(
    formatRoute({ target: 'stable', domain: 'Network', member: null }),
    '#/stable/Network',
  );
  assert.equal(formatRoute({ target: 'stable', domain: null, member: null }), '#/stable/');

  // Section routes
  assert.equal(formatRoute({ section: 'endpoints' }), '#/endpoints');
  assert.equal(formatRoute({ target: 'v8', section: 'faq' }), '#/v8/faq');

  // Default options
  assert.equal(formatRoute(), '#/');
});

test('getRedirect: resolves redirected commands', () => {
  const domains = new Map(
    [
      { domain: 'DOM', commands: [{ name: 'highlightNode', redirect: 'Overlay' }, { name: 'getDocument' }] },
      { domain: 'Page', commands: [{ name: 'deleteCookie', redirect: 'Network' }] },
      { domain: 'Overlay', commands: [{ name: 'highlightNode' }] },
      { domain: 'Network', commands: [{ name: 'deleteCookies' }] },
    ].map((d) => [d.domain, d]),
  );

  assert.deepEqual(getRedirect(domains, 'DOM', 'highlightNode'), {
    targetDomain: 'Overlay',
    targetMember: 'highlightNode',
  });
  // Pluralized destination: deleteCookie -> deleteCookies
  assert.deepEqual(getRedirect(domains, 'Page', 'deleteCookie'), {
    targetDomain: 'Network',
    targetMember: 'deleteCookies',
  });
  assert.equal(getRedirect(domains, 'DOM', 'getDocument'), null);
  assert.equal(getRedirect(domains, 'NonExistent', 'foo'), null);
  assert.equal(getRedirect(undefined, 'DOM', 'highlightNode'), null);
});

/**
 * @fileoverview Protocol Model - Isomorphic pure functions for CDP protocols.
 * Browser-agnostic, zero-DOM ES module.
 */

/** @import { ProtocolDomain, NormalizedProtocolDomain, ProtocolRoot, NormalizedProtocolRoot, TargetKind, RouteInfo } from '../types/types.d.ts' */

/** @type {Map<string, TargetKind>} */
const TARGET_MAP = new Map([
  ['tot', 'tot'],
  ['stable', 'stable'],
  ['1-3', 'stable'],
  ['1-2', 'stable'],
  ['v8', 'v8'],
]);

/**
 * Normalizes a target string to one of: 'tot', 'stable', 'v8'.
 * @param {string|null|undefined} target
 * @returns {TargetKind}
 */
export function normalizeTarget(target) {
  if (!target) return 'tot';
  return TARGET_MAP.get(target.toLowerCase()) || 'tot';
}

/**
 * Resolves the identifier property name for sorting a CDP collection.
 * @param {string} collectionName
 * @returns {string|null}
 */
function nameProperty(collectionName) {
  switch (collectionName) {
    case 'domains':
      return 'domain';
    case 'types':
      return 'id';
    case 'commands':
    case 'events':
    case 'parameters':
    case 'returns':
    case 'properties':
      return 'name';
    default:
      return null;
  }
}

/**
 * Deterministically sorts a collection in-place:
 * 1. Standard (0) before Experimental (1) before Deprecated (2).
 * 2. Required before optional.
 * 3. Alphabetical by entity name.
 *
 * @param {Array<any>} items
 * @param {string|null} prop
 */
function sortCollection(items, prop) {
  if (!prop) return;
  items.sort((a, b) => {
    // 1. Standard (0) before Experimental (1) before Deprecated (2)
    const aRank = a.deprecated ? 2 : a.experimental ? 1 : 0;
    const bRank = b.deprecated ? 2 : b.experimental ? 1 : 0;
    if (aRank !== bRank) {
      return aRank - bRank;
    }

    // 2. Required before optional
    const aOpt = a.optional ? 1 : 0;
    const bOpt = b.optional ? 1 : 0;
    if (aOpt !== bOpt) {
      return aOpt - bOpt;
    }

    // 3. Alphabetical by entity name/id
    const aName = String(a[prop] || '');
    const bName = String(b[prop] || '');
    return aName.localeCompare(bName);
  });
}

/**
 * Recursively normalizes an arbitrary CDP node without mutating original input.
 * @param {any} object
 * @param {boolean} alreadyExperimental
 * @returns {any}
 */
function normalizeNode(object, alreadyExperimental) {
  if (!object || typeof object !== 'object') {
    return object;
  }

  if (Array.isArray(object)) {
    return object.map((item) => normalizeNode(item, alreadyExperimental));
  }

  const result = /** @type {Record<string, any>} */ ({});
  const isSelfExperimental = Boolean(object.experimental);
  const childAlreadyExperimental = alreadyExperimental || isSelfExperimental;

  for (const [key, value] of Object.entries(object)) {
    // Avoid redundant experimental flag on children without mutating input
    if (key === 'experimental' && alreadyExperimental) {
      continue;
    }

    if (Array.isArray(value)) {
      result[key] = value.map((item) => normalizeNode(item, childAlreadyExperimental));
      sortCollection(result[key], nameProperty(key));
    } else {
      result[key] = normalizeNode(value, childAlreadyExperimental);
    }
  }

  return result;
}

/**
 * Normalizes protocol data by establishing empty array defaults and deterministic sorting.
 * Pure function: does NOT mutate input protocol object.
 *
 * @param {ProtocolRoot | { domains?: any[] }} protocol
 * @returns {NormalizedProtocolRoot} Normalized protocol clone
 */
export function normalizeProtocol(protocol) {
  if (!protocol || typeof protocol !== 'object') {
    return { domains: [] };
  }

  const normalized = normalizeNode(protocol, false);
  normalized.domains = normalized.domains || [];

  for (const domain of normalized.domains) {
    domain.commands = domain.commands || [];
    domain.events = domain.events || [];
    domain.types = domain.types || [];

    for (const event of domain.events) {
      event.parameters = event.parameters || [];
    }
    for (const command of domain.commands) {
      command.parameters = command.parameters || [];
      command.returns = command.returns || [];
    }
    for (const type of domain.types) {
      if (type.properties) {
        type.properties = type.properties || [];
      }
    }
  }

  return /** @type {NormalizedProtocolRoot} */ (normalized);
}

/**
 * Recursive, structurally unified deep clone filtering out anything with experimental === true.
 * Guarantees fresh copy with no shared references.
 *
 * @template T
 * @param {T} node
 * @returns {T} Fresh copy stripped of experimental entities
 */
export function stabilize(node) {
  if (typeof node !== 'object' || node === null) {
    return node;
  }

  if (Array.isArray(node)) {
    return /** @type {any} */ (
      node
        .filter((item) => !(item && typeof item === 'object' && item.experimental === true))
        .map((item) => stabilize(item))
    );
  }

  const result = /** @type {Record<string, any>} */ ({});
  for (const [key, value] of Object.entries(node)) {
    result[key] = stabilize(value);
  }

  return /** @type {T} */ (result);
}

/**
 * Helper to extract referenced type id from parameter/property object.
 * @param {string} domainName
 * @param {any} parameter
 * @returns {string|null}
 */
function getReferencedType(domainName, parameter) {
  if (!parameter || typeof parameter !== 'object') {
    return null;
  }
  if (parameter.$ref) {
    return parameter.$ref.includes('.') ? parameter.$ref : `${domainName}.${parameter.$ref}`;
  }
  if (parameter.type === 'array' && parameter.items) {
    return getReferencedType(domainName, parameter.items);
  }
  return null;
}

/**
 * Dynamically computes reverse references ("Used by") for every type across commands,
 * events, and types (properties and array items $ref).
 * Deduplicates and sorts references.
 *
 * @template {ProtocolDomain} D
 * @param {Array<D>} domains
 * @returns {Array<D>} The domains array with type.referencedBy populated
 */
export function computeBackReferences(domains) {
  if (!Array.isArray(domains)) return [];

  const typeidToType = new Map();
  for (const domain of domains) {
    for (const type of domain.types || []) {
      type.referencedBy = [];
      typeidToType.set(`${domain.domain}.${type.id}`, type);
    }
  }

  /**
   * @param {string} domainName
   * @param {any} arg
   * @param {'command' | 'event' | 'type'} type
   * @param {string} name
   */
  const addRef = (domainName, arg, type, name) => {
    const typeId = getReferencedType(domainName, arg);
    const referencedType = typeidToType.get(typeId);
    if (referencedType) {
      referencedType.referencedBy.push({ type, name });
    }
  };

  for (const domain of domains) {
    const domainName = domain.domain;

    for (const command of domain.commands || []) {
      const args = [...(command.parameters || []), ...(command.returns || [])];
      for (const arg of args) {
        addRef(domainName, arg, 'command', `${domainName}.${command.name}`);
      }
    }

    for (const event of domain.events || []) {
      for (const arg of event.parameters || []) {
        addRef(domainName, arg, 'event', `${domainName}.${event.name}`);
      }
    }

    for (const type of domain.types || []) {
      for (const prop of type.properties || []) {
        addRef(domainName, prop, 'type', `${domainName}.${type.id}`);
      }
      if (type.items) {
        addRef(domainName, type.items, 'type', `${domainName}.${type.id}`);
      }
    }
  }

  /** @type {Record<string, number>} */
  const typeOrder = { command: 1, method: 1, event: 2, type: 3 };

  for (const type of typeidToType.values()) {
    const map = new Map();
    for (const reference of type.referencedBy) {
      map.set(reference.name, reference);
    }
    type.referencedBy = Array.from(map.values());
    type.referencedBy.sort(
      (/** @type {{type: string, name: string}} */ a, /** @type {{type: string, name: string}} */ b) => {
        const orderA = typeOrder[a.type] ?? 99;
        const orderB = typeOrder[b.type] ?? 99;
        if (orderA !== orderB) {
          return orderA - orderB;
        }
        return a.name.localeCompare(b.name);
      },
    );
  }

  return domains;
}

/**
 * Resolves where a redirected command now lives. Only commands carry `redirect` in the protocol.
 * Matches a pluralized name in the destination (Page.deleteCookie -> Network.deleteCookies).
 * @param {Map<string, ProtocolDomain> | undefined} domains
 * @param {string} domainName
 * @param {string} memberName
 * @returns {{ targetDomain: string, targetMember: string } | null}
 */
export function getRedirect(domains, domainName, memberName) {
  const command = domains?.get(domainName)?.commands?.find((c) => c.name === memberName);
  if (!command?.redirect) return null;
  const match = domains
    ?.get(command.redirect)
    ?.commands?.find((c) => c.name === memberName || c.name === `${memberName}s`);
  return { targetDomain: command.redirect, targetMember: match?.name ?? memberName };
}

/**
 * Creates canonical RouteInfo, mapping lowercase landing anchors to section.
 * @param {TargetKind} target
 * @param {string|null} domain
 * @param {string|null} member
 * @returns {RouteInfo}
 */
function createRouteInfo(target, domain, member) {
  if (domain && !/^[A-Z][a-zA-Z0-9]*$/.test(domain)) {
    const full = member ? `${domain}.${member}` : domain;
    const section = full === 'http-endpoints' ? 'endpoints' : full;
    return { target, domain: null, member: null, section };
  }
  return { target, domain, member };
}

/**
 * Parses a hash route into a canonical RouteInfo object.
 * Legacy static URLs (/tot/Page/#method-navigate, /1-3/..., /v8/...) are rewritten to hash
 * routes by the generated domain stubs and 404.html before the app ever sees them.
 *
 * Supported: #/Page.navigate, #/Page, #/v8/Runtime.evaluate, #/stable/Network, #/v8/, #faq, #/endpoints
 *
 * @param {string|null} [hash]
 * @returns {RouteInfo}
 */
export function parseRoute(hash) {
  const path = (hash ?? '').trim().replace(/^#\/?/, '').replace(/\/+$/, '');
  const [first = '', ...rest] = path.split('/');
  const matchedTarget = TARGET_MAP.get(first.toLowerCase());
  const target = matchedTarget ?? 'tot';
  const ref = matchedTarget ? rest.join('/') : path;
  if (!ref) return createRouteInfo(target, null, null);

  const dot = ref.indexOf('.');
  if (dot === -1) return createRouteInfo(target, ref, null);
  return createRouteInfo(target, ref.slice(0, dot), ref.slice(dot + 1) || null);
}

/**
 * Formats canonical hash route from components.
 * @param {{ target?: string|null, domain?: string|null, member?: string|null, section?: string|null }} [route]
 * @returns {string} Canonical hash route, e.g. '#/Page.navigate'
 */
export function formatRoute({ target = 'tot', domain = null, member = null, section = null } = {}) {
  const normTarget = normalizeTarget(target);
  const targetPrefix = normTarget === 'tot' ? '' : `${normTarget}/`;

  if (section) {
    return `#/${targetPrefix}${section}`;
  }
  if (!domain) {
    return normTarget === 'tot' ? '#/' : `#/${targetPrefix}`;
  }
  if (member) {
    return `#/${targetPrefix}${domain}.${member}`;
  }
  return `#/${targetPrefix}${domain}`;
}

/**
 * @fileoverview Fuzzy search controller and UI rendering for protocol entities.
 */

/** @import { ProtocolDomain } from '../types/types.d.ts' */

import { FuzzySearch } from './fuzzy_search.js';
import { ProtocolRenderer } from './protocol_renderer.js';

// Number of search results to render immediately.
const SEARCH_RENDER_COUNT = 50;

/** @typedef {'method' | 'event' | 'type'} SearchItemKind */

const SearchItemType = {
  Method: 'method',
  Type: 'type',
  Event: 'event',
};

/**
 * @param {HTMLElement|null} target
 * @param {HTMLInputElement} searchInput
 * @returns {boolean}
 */
function isEditableOrActive(target, searchInput) {
  if (
    target &&
    target.matches &&
    target.matches('input, textarea, select, [contenteditable="true"]')
  ) {
    return true;
  }
  return searchInput === document.activeElement;
}

class SearchItem {
  /**
   * @param {string} domainName
   * @param {string} domainEntry
   * @param {SearchItemKind} itemType
   * @param {string} [description]
   * @param {(ref: string) => string} [formatRef]
   */
  constructor(domainName, domainEntry, itemType, description, formatRef) {
    this.domainName = domainName;
    this.domainEntry = domainEntry;
    this.type = itemType;
    this.description = description || '';
    this.title = this.domainName + '.' + this.domainEntry;
    const refFormatter = formatRef || (typeof window !== 'undefined' && window.app?.formatRef);
    this.route = refFormatter ? refFormatter(this.title) : '#/' + this.title;
  }
}

class SearchResult {
  /**
   * @param {SearchItem} item
   * @param {number} score
   * @param {Array<number>} matches
   */
  constructor(item, score, matches) {
    this.item = item;
    this.score = score;
    this.matches = matches;
  }
}

export class Search {
  /** @type {typeof SearchItemType} */
  static ItemType;
  /** @type {typeof SearchItem} */
  static Item;
  /** @type {typeof SearchResult} */
  static SearchResult;

  /**
   * @param {Element} searchHeader
   * @param {Element} resultsElement
   * @param {{ navigate?: (route: string) => void, formatRef?: (ref: string) => string, focusContent?: () => void, redirectFor?: (domain: string, member: string) => { targetDomain: string, targetMember: string } | null }} [app]
   */
  constructor(searchHeader, resultsElement, app) {
    this._app = app;
    const input =
      searchHeader.tagName === 'INPUT'
        ? searchHeader
        : searchHeader.querySelector('input') || searchHeader;
    this._searchInput = /** @type {HTMLInputElement} */ (input);
    /** @type {Array<SearchItem>} */
    this._items = [];
    /** @type {Element|null} */
    this._selectedElement = null;
    this._searchInput.addEventListener('input', this._onInput.bind(this), false);
    this._searchInput.addEventListener('keydown', this._onKeyDown.bind(this), false);
    this._resultsElement = resultsElement;

    document.addEventListener('keydown', (event) => {
      const target = /** @type {HTMLElement|null} */ (event.target);
      if (isEditableOrActive(target, this._searchInput)) return;
      if (event.key === '/' || ((event.metaKey || event.ctrlKey) && event.key === 'k')) {
        event.preventDefault();
        this._searchInput.focus();
        this._searchInput.select();
        return;
      }
      if (event.key === 'Backspace' || event.key === 'Delete') {
        this._searchInput.focus();
        return;
      }
      if (
        event.key.length === 1 &&
        !event.ctrlKey &&
        !event.metaKey &&
        !event.altKey &&
        /\S/.test(event.key)
      ) {
        this._searchInput.value = '';
        this._searchInput.focus();
      }
    });

    document.addEventListener('paste', (event) => {
      const target = /** @type {HTMLElement|null} */ (event.target);
      if (isEditableOrActive(target, this._searchInput)) return;
      this._searchInput.focus();
    });

    document.addEventListener('click', (event) => {
      const target = /** @type {HTMLElement|null} */ (event.target);
      if (!target || this._searchInput.contains(target)) return;
      const searchItem = /** @type {HTMLElement|null} */ (target.closest('.search-item'));
      if (searchItem) {
        event.preventDefault();
        event.stopPropagation();
        this.cancelSearch();
        const navigate =
          this._app?.navigate || (typeof window !== 'undefined' && window.app?.navigate);
        if (navigate && searchItem.dataset.route) navigate(searchItem.dataset.route);
        return;
      }
    });
  }

  /**
   * @param {Array<ProtocolDomain>} domains
   */
  setDomains(domains) {
    this._items = [];
    const formatRef = this._app?.formatRef;
    for (const domain of domains) {
      for (const command of domain.commands || []) {
        const redirect = this._app?.redirectFor?.(domain.domain, command.name);
        const description = redirect
          ? `Moved to ${redirect.targetDomain}.${redirect.targetMember}.`
          : command.description;
        this._items.push(
          new SearchItem(domain.domain, command.name, 'method', description, formatRef),
        );
      }
      for (const event of domain.events || []) {
        this._items.push(
          new SearchItem(domain.domain, event.name, 'event', event.description, formatRef),
        );
      }
      for (const type of domain.types || []) {
        this._items.push(
          new SearchItem(domain.domain, type.id, 'type', type.description, formatRef),
        );
      }
    }
  }

  /**
   * Runs a search for `query` and opens the results dropdown.
   * @param {string} query
   */
  search(query) {
    this._searchInput.value = query;
    this._searchInput.focus();
    this._onInput();
  }

  cancelSearch() {
    this._searchInput.blur();
    /** @type {HTMLElement} */ (this._resultsElement).style.setProperty('display', 'none');
    this._searchInput.value = '';
    setQueryParam('');
    if (this._app?.focusContent) this._app.focusContent();
    else if (typeof window !== 'undefined' && window.app?.focusContent) window.app.focusContent();
  }

  _onInput() {
    this._selectedElement = null;
    /** @type {HTMLElement} */ (this._resultsElement).style.setProperty('display', 'block');
    let query = this._searchInput.value.trim();
    setQueryParam(query);
    let items = this._items;
    let results = this._doSearch(items, query);
    if (results.length === 0) {
      this._renderMessage('Nothing is found.');
      return;
    }
    this._resultsElement.textContent = '';
    if (!query) this._addNavigateHomeItem();
    for (let i = 0; i < Math.min(results.length, SEARCH_RENDER_COUNT); ++i)
      this._resultsElement.appendChild(renderSearchResult(results[i]));
    this._addAllResultsButtonIfNeeded(results);
    this._selectedElement = /** @type {Element|null} */ (this._resultsElement.firstChild);
    if (this._selectedElement) this._selectedElement.classList.add('selected');
  }

  _addNavigateHomeItem() {
    let main = document.createElement('div');
    main.className = 'hbox search-item custom-search-result';
    main.textContent = 'Navigate Home';
    main.dataset.route = '#/';
    this._resultsElement.appendChild(main);
  }

  /**
   * @param {Array<SearchResult>} results
   * @returns {HTMLElement|undefined}
   */
  _addAllResultsButtonIfNeeded(results) {
    let remainingResults = results.length - SEARCH_RENDER_COUNT;
    if (remainingResults <= 0) return;
    let main = document.createElement('div');
    main.className = 'hbox search-item custom-search-result monospace';
    main.textContent = `Show Remaining ${remainingResults} Results...`;
    main.addEventListener(
      'click',
      (event) => {
        event.preventDefault();
        event.stopPropagation();
        for (let i = SEARCH_RENDER_COUNT; i < results.length; ++i)
          this._resultsElement.appendChild(renderSearchResult(results[i]));
        let next = /** @type {Element|null} */ (main.nextSibling);
        main.remove();
        this._selectElement(next);
        this._searchInput.focus();
      },
      false,
    );
    this._resultsElement.appendChild(main);
    return main;
  }

  /**
   * @param {string} text
   */
  _renderMessage(text) {
    this._resultsElement.textContent = '';
    const box = document.createElement('div');
    box.className = 'box search-results-message';
    const h4 = document.createElement('h4');
    h4.textContent = text;
    box.appendChild(h4);
    this._resultsElement.appendChild(box);
  }

  /**
   * @param {Array<SearchItem>} items
   * @param {string} query
   * @returns {Array<SearchResult>}
   */
  _doSearch(items, query) {
    let results = [];
    if (!query) {
      for (let item of items) results.push(new SearchResult(item, 0, []));
      return results;
    }

    let fuzzySearch = new FuzzySearch(query);
    for (let item of items) {
      /** @type {Array<number>} */
      let matches = [];
      let score = fuzzySearch.score(item.title, matches);
      if (score === 0) continue;
      results.push(new SearchResult(item, score, matches));
    }
    results.sort((/** @type {SearchResult} */ a, /** @type {SearchResult} */ b) => {
      const scoreDiff = b.score - a.score;
      if (scoreDiff) return scoreDiff;
      // Prefer left-most search results.
      const startDiff = (a.matches[0] ?? 0) - (b.matches[0] ?? 0);
      if (startDiff) return startDiff;
      return a.item.title.length - b.item.title.length;
    });
    return results;
  }

  /**
   * @param {KeyboardEvent} event
   */
  _onKeyDown(event) {
    if (event.key === 'Escape' || event.keyCode === 27) {
      event.preventDefault();
      event.stopPropagation();
      this.cancelSearch();
    } else if (event.key === 'ArrowDown') {
      this._selectNext(event);
    } else if (event.key === 'ArrowUp') {
      this._selectPrevious(event);
    } else if (event.key === 'Enter') {
      event.preventDefault();
      event.stopPropagation();
      if (this._selectedElement) /** @type {HTMLElement} */ (this._selectedElement).click();
    }
  }

  /**
   * @param {Event} event
   */
  _selectNext(event) {
    if (!this._selectedElement) return;
    event.preventDefault();
    event.stopPropagation();
    let next = /** @type {Element|null} */ (this._selectedElement.nextSibling);
    if (!next) next = /** @type {Element|null} */ (this._resultsElement.firstChild);
    this._selectElement(next);
  }

  /**
   * @param {Event} event
   */
  _selectPrevious(event) {
    if (!this._selectedElement) return;
    event.preventDefault();
    event.stopPropagation();
    let previous = /** @type {Element|null} */ (this._selectedElement.previousSibling);
    if (!previous) previous = /** @type {Element|null} */ (this._resultsElement.lastChild);
    this._selectElement(previous);
  }

  /**
   * @param {Element|null} item
   */
  _selectElement(item) {
    if (this._selectedElement) this._selectedElement.classList.remove('selected');
    this._selectedElement = item;
    if (this._selectedElement) {
      this._selectedElement.classList.add('selected');
      if (typeof this._selectedElement.scrollIntoViewIfNeeded === 'function')
        this._selectedElement.scrollIntoViewIfNeeded(false);
    }
  }
}

/**
 * Mirrors the search query into `?q=` (or removes it) without adding history entries.
 * @param {string} query
 */
function setQueryParam(query) {
  const search = query ? `?q=${encodeURIComponent(query)}` : '';
  if (search === location.search) return;
  history.replaceState(null, '', location.pathname + search + location.hash);
}

/**
 * @param {SearchResult} searchResult
 * @returns {Element}
 */
function renderSearchResult(searchResult) {
  let item = searchResult.item;
  let main = document.createElement('div');
  main.className = 'hbox search-item';
  let icon = document.createElement('span');
  icon.className = 'search-item-icon';
  main.appendChild(icon);
  icon.appendChild(ProtocolRenderer.renderEntityIcon(item.type));
  {
    let container = document.createElement('div');
    container.className = 'search-item-main';
    main.appendChild(container);
    let p1 = document.createElement('div');
    p1.className = 'search-item-title monospace';
    container.appendChild(p1);
    let domainElement = document.createElement('span');
    domainElement.className = 'search-item-title-domain';
    p1.appendChild(domainElement);
    domainElement.appendChild(
      renderTextWithMatches(item.title, searchResult.matches, 0, item.domainName.length + 1),
    );
    p1.appendChild(
      renderTextWithMatches(
        item.title,
        searchResult.matches,
        item.domainName.length + 1,
        item.title.length,
      ),
    );
    let p2 = document.createElement('div');
    p2.className = 'search-item-description';
    p2.textContent = item.description;
    container.appendChild(p2);
  }
  main.dataset.route = item.route;
  return main;
}

/**
 * @param {string} text
 * @param {Array<number>} matches
 * @param {number} fromIndex
 * @param {number} toIndex
 * @returns {Node}
 */
function renderTextWithMatches(text, matches, fromIndex, toIndex) {
  if (!matches.length) return document.createTextNode(text.substring(fromIndex, toIndex));
  let result = document.createDocumentFragment();
  let insideMatch = false;
  let currentIndex = fromIndex;
  let matchIndex = new Set(matches);
  for (let i = fromIndex; i < toIndex; ++i) {
    if (insideMatch !== matchIndex.has(i)) {
      add(currentIndex, i, insideMatch);
      insideMatch = matchIndex.has(i);
      currentIndex = i;
    }
  }
  add(currentIndex, toIndex, insideMatch);
  return result;

  /**
   * @param {number} from
   * @param {number} to
   * @param {boolean} isHighlight
   */
  function add(from, to, isHighlight) {
    if (to === from) return;
    const chunk = text.substring(from, to);
    if (isHighlight) {
      const span = document.createElement('span');
      span.className = 'search-highlight';
      span.textContent = chunk;
      result.appendChild(span);
    } else {
      result.appendChild(document.createTextNode(chunk));
    }
  }
}

