// @ts-check
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';

/** @type {Record<string, string>} */
const MIME_TYPES = {
  '.html': 'text/html; charset=UTF-8',
  '.js': 'application/javascript; charset=UTF-8',
  '.mjs': 'application/javascript; charset=UTF-8',
  '.css': 'text/css; charset=UTF-8',
  '.json': 'application/json; charset=UTF-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=UTF-8',
};

/**
 * Creates and starts a lightweight static HTTP server with GitHub Pages 404 fallback.
 * @param {string} [root]
 * @param {number} [port]
 * @returns {Promise<{ server: import('node:http').Server, url: string, close: () => Promise<void> }>}
 */
export function createStaticServer(root = process.cwd(), port = 8696) {
  return new Promise((resolve, reject) => {
    const server = http.createServer((req, res) => {
      const urlPath = (req.url || '/').split('?')[0].split('#')[0];
      let safePath = path.normalize(urlPath).replace(/^(\.\.[/\\])+/, '');
      let filePath = path.join(root, safePath);

      if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
        filePath = path.join(filePath, 'index.html');
      }

      if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
        const notFoundPath = path.join(root, '404.html');
        if (fs.existsSync(notFoundPath)) {
          res.writeHead(404, {
            'Content-Type': 'text/html; charset=UTF-8',
            'Access-Control-Allow-Origin': '*',
          });
          fs.createReadStream(notFoundPath).pipe(res);
          return;
        }
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=UTF-8' });
        res.end(`Not Found: ${urlPath}\n`);
        return;
      }

      const ext = path.extname(filePath).toLowerCase();
      const contentType = MIME_TYPES[ext] || 'application/octet-stream';

      res.writeHead(200, {
        'Content-Type': contentType,
        'Access-Control-Allow-Origin': '*',
      });
      fs.createReadStream(filePath).pipe(res);
    });

    server.listen(port, () => {
      const addr = server.address();
      const actualPort = typeof addr === 'object' && addr ? addr.port : port;
      const url = `http://127.0.0.1:${actualPort}`;
      resolve({
        server,
        url,
        close: () => new Promise((res, rej) => server.close((err) => (err ? rej(err) : res()))),
      });
    });

    server.on('error', reject);
  });
}

// If executed directly from CLI:
if (import.meta.url === `file://${process.argv[1]}`) {
  const port = Number(process.env.PORT) || 8696;
  createStaticServer(process.cwd(), port).then(({ url }) => {
    console.log(`Serving ${url}/devtools-protocol/`);
  });
}

export type { Protocol } from 'devtools-protocol';
import type { IProtocol, Protocol as ProtocolSchema } from './protocol-schema.d.ts';

export type { IProtocol } from './protocol-schema.d.ts';

export type ProtocolCommand = ProtocolSchema.Command;
export type ProtocolEvent = ProtocolSchema.Event;

export interface ProtocolBackReference {
  type: 'command' | 'event' | 'type';
  name: string;
}

/** Flattened protocol parameter / property for viewer traversal */
export interface ProtocolParameter {
  name?: string;
  type?: string;
  $ref?: string;
  description?: string;
  optional?: boolean;
  experimental?: boolean;
  deprecated?: boolean;
  items?: ProtocolParameter;
  enum?: string[];
  properties?: ProtocolParameter[];
}

/** Flattened domain type representation including runtime back-references */
export interface ProtocolType {
  id: string;
  type?: string;
  description?: string;
  experimental?: boolean;
  deprecated?: boolean;
  properties?: ProtocolParameter[];
  enum?: string[];
  items?: ProtocolParameter;
  referencedBy?: ProtocolBackReference[];
}

export interface ProtocolDomain {
  domain: string;
  description?: string;
  experimental?: boolean;
  deprecated?: boolean;
  dependencies?: string[];
  types?: ProtocolType[];
  commands?: ProtocolCommand[];
  events?: ProtocolEvent[];
}

export interface NormalizedProtocolDomain extends ProtocolDomain {
  types: ProtocolType[];
  commands: ProtocolCommand[];
  events: ProtocolEvent[];
}

export interface ProtocolRoot {
  version?: ProtocolSchema.Version;
  domains: ProtocolDomain[];
}

export interface NormalizedProtocolRoot {
  version?: ProtocolSchema.Version;
  domains: NormalizedProtocolDomain[];
}

export type TargetKind = 'tot' | 'stable' | 'v8';

export interface RouteInfo {
  target: TargetKind;
  domain: string | null;
  member: string | null;
  section?: string | null;
}

/**  Definition for protocol.json types.  Vendored from https://github.com/ChromeDevTools/devtools-protocol/blob/master/scripts/protocol-schema.d.ts */
export interface IProtocol {
  version: Protocol.Version;
  domains: Protocol.Domain[];
}

export namespace Protocol {
  export interface Version {
    major: string;
    minor: string;
  }

  export interface ExtraInformation {
    deprecated?: boolean;
    experimental?: boolean;
  }

  export interface Domain extends ExtraInformation {
    /** Name of domain */
    domain: string;
    /** Description of the domain */
    description?: string;
    /** Dependencies on other domains */
    dependencies?: string[];
    /** Types used by the domain. */
    types?: DomainType[];
    /** Commands accepted by the domain */
    commands?: Command[];
    /** Events fired by domain */
    events?: Event[];
  }

  export interface Command extends Event {
    returns?: PropertyType[];
    async?: boolean;
    redirect?: string;
  }

  export interface Event extends ExtraInformation {
    name: string;
    parameters?: PropertyType[];
    /** Description of the event */
    description?: string;
  }

  export interface ArrayType {
    type: 'array';
    /** Maps to a typed array e.g string[] */
    items: RefType | PrimitiveType | StringType | AnyType | ObjectType;
    /** Cardinality of length of array type */
    minItems?: number;
    maxItems?: number;
  }

  export interface ObjectType {
    type: 'object';
    /** Properties of the type. Maps to a typed object */
    properties?: PropertyType[];
  }

  export interface StringType {
    type: 'string';
    /** Possible values of a string. */
    enum?: string[];
  }

  export interface PrimitiveType {
    type: 'number' | 'integer' | 'boolean';
  }

  export interface AnyType {
    type: 'any';
  }

  export interface RefType {
    /** Reference to a domain defined type */
    $ref: string;
  }

  export interface PropertyBaseType {
    /** Name of param */
    name: string;
    /** Is the property optional ? */
    optional?: boolean;
    /** Description of the type */
    description?: string;
  }

  type DomainType = {
    /** Name of property */
    id: string;
    /** Description of the type */
    description?: string;
  } & (StringType | ObjectType | ArrayType | PrimitiveType) &
    ExtraInformation;

  type ProtocolType = StringType | ObjectType | ArrayType | PrimitiveType | RefType | AnyType;

  type PropertyType = PropertyBaseType & ProtocolType;
}

/**
 * @fileoverview Bling JS: Syntactic sugar for DOM queries.
 * Defines global $ and $$ helpers and element-scoped equivalents.
 * With automagic qSA types.
 *
 * Inspired by my original Bling.js Gist (2015): https://gist.github.com/paulirish/12fb951a8b893a454b32
 * But.. it's different. and upgraded.
 */

/** @import { ParseSelector } from '../types/bling.d.ts' */

/**
 * querySelector that throws if nothing matches. Return type is inferred from the selector literal via ParseSelector.
 * @template {string} T
 * @param {T} query
 * @param {ParentNode} [context]
 * @returns {ParseSelector<T>}
 */
export function $(query, context) {
  const result = (context ?? document).querySelector(query);
  if (result === null) throw new Error(`querySelector('${query}') not found`);
  return /** @type {ParseSelector<T>} */ (result);
}

/**
 * querySelectorAll that returns an Array. Return type is inferred from the selector literal via ParseSelector.
 * @template {string} T
 * @param {T} query
 * @param {ParentNode} [context]
 * @returns {ParseSelector<T>[]}
 */
export function $$(query, context) {
  return /** @type {ParseSelector<T>[]} */ (
    Array.from((context ?? document).querySelectorAll(query))
  );
}

if (typeof Element !== 'undefined') {
  for (const Ctor of [Element, Document, DocumentFragment]) {
    Object.defineProperties(Ctor.prototype, {
      $: {
        /**
         * @template {string} T
         * @this {ParentNode}
         * @param {T} query
         * @returns {ParseSelector<T>}
         */
        value: function (query) {
          return $(query, this);
        },
        writable: true,
        configurable: true,
        enumerable: false,
      },
      $$: {
        /**
         * @template {string} T
         * @this {ParentNode}
         * @param {T} query
         * @returns {ParseSelector<T>[]}
         */
        value: function (query) {
          return $$(query, this);
        },
        writable: true,
        configurable: true,
        enumerable: false,
      },
    });
  }
}

if (typeof window !== 'undefined') {
  window.$ = $;
  window.$$ = $$;
}
